// Prepare and upload the 16 draft illustrations for the 2026-11-22 library
// expansion (ex-172..ex-187), generated by Codex and selected in
// docs/exercises-review/expansion-2026-11-22/image-manifest.json.
//
//   Dry run (default) - writes the variants locally, touches no bucket:
//     npx tsx scripts/upload-exercise-images-expansion-2026-11-22.ts --src=<dir> --out=<dir>
//   Upload - you must name the bucket, and it must match the env file's bucket:
//     npx tsx --env-file=.env.development scripts/upload-exercise-images-expansion-2026-11-22.ts \
//       --src=<dir> --upload --bucket=<FIREBASE_ADMIN_STORAGE_BUCKET>
//
// Safety, because the shared exercise-images/ prefix holds the whole live
// library:
// - Only the 16 ids below, each checked to be a record in
//   EXPANSION_2026_11_22 with the expected slug, and each source file checked
//   against the manifest's sha256 (so a rejected original can't slip in).
// - Create-only: every write carries ifGenerationMatch: 0, so an existing
//   object is never replaced. A rerun skips objects whose bytes already match
//   and fails on any that differ.
//
// Writes the same objects as upload-exercise-images-168-170.ts: {id}.png (960),
// {id}-320.webp, {id}-960.webp and {id}-pdf.png (216). The supplied art has no
// footer band; the one landscape image (ex-174) has the strip with the
// shoulder trimmed off, then is padded to a square by repeating its edge
// pixels (plain wall above, table below), so no fingers are cropped.
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

import sharp from "sharp";

import { EXPANSION_2026_11_22 } from "../lib/exercises-expansion-2026-11-22";

type Crop = { left: number; top: number; width: number; height: number };
type Source = { id: string; slug: string; file: string; sha256: string; crop?: Crop };

const SOURCES: Source[] = [
  // ex-172 and ex-185 use v2: the originals showed the tongue lying on the
  // lower teeth and the head tipped back. Regenerated with Codex image edit
  // 2026-11-22; the originals must not be uploaded.
  { id: "ex-172", slug: "controlled-jaw-opening", file: "controlled-jaw-opening-v2.png", sha256: "ec252bbf04874eb829f644b36b6fba9718934cad6784f8f4860d43ee9132218f" },
  { id: "ex-173", slug: "thumb-opposition", file: "thumb-opposition.png", sha256: "6f40638281c6226ebc3d165145d7092c9320185cfea995464d001deaf068f9fc" },
  { id: "ex-174", slug: "thumb-palmar-abduction", file: "thumb-palmar-abduction-v2.png", sha256: "e0d8c65f01e539747babb6b50227969f511c96af5dd02250af205d930807b880",
    // Landscape 1536x1024. Drop the 310px strip holding the shoulder (edge
    // padding streaks it) - the forearm, thumb and all fingertips stay whole.
    crop: { left: 310, top: 0, width: 1226, height: 1024 } },
  { id: "ex-175", slug: "finger-spread-and-close", file: "finger-spread-and-close.png", sha256: "117503817c5abb0759ac1695eb2f9058ac0488ca164589eac92ccb55f289b3a5" },
  { id: "ex-176", slug: "short-foot-exercise", file: "short-foot-doming.png", sha256: "592a834af5a12fcf6296c661af72c1244475eccda84328dd9608457493caccde" },
  { id: "ex-177", slug: "toe-yoga", file: "toe-yoga.png", sha256: "5d7e95c1f5ba187505ac0a8c0e8a32efa4bbed8b4c3abdb6f6e0e7e80dbebd12" },
  { id: "ex-178", slug: "seated-plantar-fascia-stretch", file: "plantar-fascia-seated-stretch.png", sha256: "2b25db63a967730c9fd284b37209ba9911acc52b38ef93a08578f9f2956acb9b" },
  { id: "ex-179", slug: "resisted-ankle-inversion", file: "resisted-ankle-inversion-v2.png", sha256: "0c0e681998e502e05ebc3129656265f950f7bbf015edc627c9f4bae346ce532c" },
  { id: "ex-180", slug: "resisted-ankle-dorsiflexion", file: "resisted-ankle-dorsiflexion.png", sha256: "0b0470e58497d54e9a843808c9a7ee3c42feaa0d35fd849e8bc0058fb2ffaf4c" },
  { id: "ex-181", slug: "calf-stretch-soleus", file: "bent-knee-calf-stretch-v2.png", sha256: "910f3139677d35a51a5c8d78d094b7a89d43ff707aa7f31bc926378ba74df4bf" },
  { id: "ex-182", slug: "hamstring-heel-dig-hold", file: "hamstring-heel-dig-isometric.png", sha256: "54951e060e8ec3e2baa42e007c84834b7129b60ee1a324c4ef885daede3ccf46" },
  { id: "ex-183", slug: "prone-hamstring-curl-with-band", file: "prone-band-hamstring-curl.png", sha256: "d3e3fc818ca05ad26b1e9000bedd605038b52b5fbed7979f68a4d201dac630dd" },
  { id: "ex-184", slug: "adductor-squeeze", file: "supine-adductor-squeeze.png", sha256: "e60c3907c8d0f34449be26d4521ce7a3b8a0814cd4eb523932c94367038ea66b" },
  { id: "ex-185", slug: "seated-thoracic-extension", file: "seated-thoracic-extension-v2.png", sha256: "904f5e37792c4acd2da8870dda851bc0c0a7ef7370c670d086ba8d1979960c75" },
  { id: "ex-186", slug: "gaze-stabilisation-vor-x1", file: "seated-vor-x1.png", sha256: "987f8abf9d31cf0e8251f831087dbc03ce7a302a682445d0983944f319eb4487" },
  { id: "ex-187", slug: "pursed-lip-breathing", file: "pursed-lip-breathing.png", sha256: "f55c5376e859e276f1e2e2278f69620585d6eed8773e83283d8d235081cf6f6b" },
];

const CACHE_CONTROL = "public,max-age=86400,stale-while-revalidate=604800";

// One image at a time with no libvips cache: a full run was OOM-killed on a
// busy machine with sharp's defaults.
sharp.cache(false);
sharp.concurrency(1);

function arg(name: string): string | undefined {
  const hit = process.argv.find((a) => a.startsWith(`--${name}=`));
  return hit?.slice(name.length + 3);
}

const md5 = (data: Buffer) => createHash("md5").update(data).digest("base64");

/** Square the artwork without cropping: pad the short side by repeating edge pixels. */
async function square(input: Buffer): Promise<Buffer> {
  const { width, height } = await sharp(input).metadata();
  if (!width || !height) throw new Error("unreadable image");
  if (width === height) return input;
  const gap = Math.abs(width - height);
  const before = Math.floor(gap / 2);
  const after = gap - before;
  return sharp(input)
    .extend(
      width > height
        ? { top: before, bottom: after, extendWith: "copy" }
        : { left: before, right: after, extendWith: "copy" },
    )
    .toBuffer();
}

async function variants(input: Buffer, crop?: Crop) {
  const trimmed = crop ? await sharp(input).extract(crop).toBuffer() : input;
  const src = sharp(await square(trimmed));
  const fit = { fit: "inside" as const, withoutEnlargement: true };
  return {
    png: await src.clone().resize(960, 960, fit).png({ compressionLevel: 9 }).toBuffer(),
    webp320: await src.clone().resize(320, 320, fit).webp({ quality: 82 }).toBuffer(),
    webp960: await src.clone().resize(960, 960, fit).webp({ quality: 85 }).toBuffer(),
    pdf: await src.clone().resize(216, 216, fit).png({ compressionLevel: 9 }).toBuffer(),
  };
}

function checkSources(srcDir: string): Map<string, { bytes: Buffer; crop?: Crop }> {
  const drafts = new Map(EXPANSION_2026_11_22.map((e) => [e.id, e]));
  const out = new Map<string, { bytes: Buffer; crop?: Crop }>();
  for (const s of SOURCES) {
    const record = drafts.get(s.id);
    if (!record) throw new Error(`${s.id} is not in EXPANSION_2026_11_22 - refusing`);
    if (record.slug !== s.slug) throw new Error(`${s.id}: slug ${record.slug} != ${s.slug}`);
    const bytes = readFileSync(path.join(srcDir, s.file));
    const hash = createHash("sha256").update(bytes).digest("hex");
    if (hash !== s.sha256) throw new Error(`${s.file}: sha256 ${hash} does not match the selected manifest`);
    out.set(s.id, { bytes, crop: s.crop });
  }
  if (new Set(SOURCES.map((s) => s.id)).size !== SOURCES.length) throw new Error("duplicate id in SOURCES");
  return out;
}

type Bucket = {
  name: string;
  file(name: string): {
    exists(): Promise<[boolean]>;
    getMetadata(): Promise<[{ md5Hash?: string; generation?: string | number }]>;
    save(data: Buffer, opts: object): Promise<void>;
  };
};

async function openBucket(): Promise<Bucket> {
  const wanted = arg("bucket");
  const configured = process.env.FIREBASE_ADMIN_STORAGE_BUCKET;
  const raw = process.env.FIREBASE_SERVICE_ACCOUNT_JSON;
  if (!raw) throw new Error("FIREBASE_SERVICE_ACCOUNT_JSON is not set");
  if (!configured) throw new Error("FIREBASE_ADMIN_STORAGE_BUCKET is not set");
  if (!wanted) throw new Error("--upload needs --bucket=<name> naming the target bucket explicitly");
  if (wanted !== configured) throw new Error(`--bucket=${wanted} does not match the env file's bucket ${configured}`);
  const { cert, getApps, initializeApp } = await import("firebase-admin/app");
  const { getStorage } = await import("firebase-admin/storage");
  if (!getApps().length) initializeApp({ credential: cert(JSON.parse(raw)), storageBucket: configured });
  return getStorage().bucket() as unknown as Bucket;
}

async function main() {
  const srcDir = arg("src");
  if (!srcDir) throw new Error("pass --src=<output/imagegen/physioonclick-expansion-2026-11-22>");
  const upload = process.argv.includes("--upload");
  const outDir = arg("out");
  if (!upload && !outDir) throw new Error("dry run: pass --out=<dir> to write the variants locally (or --upload)");

  const sources = checkSources(srcDir);
  const bucket = upload ? await openBucket() : null;
  if (bucket) console.log(`Uploading (create-only) to ${bucket.name}`);

  const created: string[] = [];
  for (const [id, { bytes, crop }] of sources) {
    const v = await variants(bytes, crop);
    const objects: [string, Buffer, string][] = [
      [`${id}.png`, v.png, "image/png"],
      [`${id}-320.webp`, v.webp320, "image/webp"],
      [`${id}-960.webp`, v.webp960, "image/webp"],
      [`${id}-pdf.png`, v.pdf, "image/png"],
    ];
    for (const [object, data, contentType] of objects) {
      if (!bucket) {
        mkdirSync(outDir!, { recursive: true });
        writeFileSync(path.join(outDir!, object), data);
        continue;
      }
      const file = bucket.file(`exercise-images/${object}`);
      const [exists] = await file.exists();
      if (exists) {
        const [meta] = await file.getMetadata();
        if (meta.md5Hash === md5(data)) {
          console.log(`  skip ${object} (identical object already there)`);
          continue;
        }
        throw new Error(`exercise-images/${object} already exists with different bytes - refusing to overwrite`);
      }
      await file.save(data, {
        contentType,
        resumable: false,
        metadata: { cacheControl: CACHE_CONTROL },
        preconditionOpts: { ifGenerationMatch: 0 },
      });
      const [meta] = await file.getMetadata();
      created.push(`exercise-images/${object}#${meta.generation}`);
    }
    console.log(`${id}: ${objects.map(([o, d]) => `${o} ${d.length}B`).join(", ")}`);
  }
  if (bucket) {
    // Scoped rollback list: only objects this run created.
    console.log(`\nCreated ${created.length} objects:\n${created.join("\n")}`);
  }
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
